import { defineConfig, configDefaults } from 'vitest/config';

export default defineConfig({
  test: {
    setupFiles: ['./vitest.setup.ts'],
    // `android/`/`ios/` are gitignored native build output (regenerated by
    // `expo prebuild`/`expo run:*`) — Vitest's own file watcher scanning
    // into a live Gradle build tree has been observed to throw a transient
    // EPERM on a locked intermediate file. Excluding them alongside the
    // framework's own defaults is cheap and avoids that flakiness for
    // anyone who has built natively on this machine.
    exclude: [...configDefaults.exclude, 'android/**', 'ios/**'],
  },
});
